PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE d1_migrations(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE `users` (
    `id` TEXT PRIMARY KEY NOT NULL,
    `name` TEXT NOT NULL,
    `email` TEXT NOT NULL UNIQUE,
    `role` TEXT NOT NULL DEFAULT 'viewer' CHECK(`role` IN ('admin', 'viewer')),
    `created_at` INTEGER NOT NULL,
    `updated_at` INTEGER NOT NULL,
    `deleted_at` INTEGER
, `email_verified` INTEGER NOT NULL DEFAULT 0, `image` TEXT);
CREATE TABLE `persons` (
    `id` TEXT PRIMARY KEY NOT NULL,
    `name` TEXT NOT NULL,
    `is_daughter` INTEGER NOT NULL DEFAULT 0,
    `created_at` INTEGER NOT NULL,
    `updated_at` INTEGER NOT NULL,
    `deleted_at` INTEGER
, `relationship` TEXT CHECK (`relationship` IN ('father', 'mother', 'son', 'daughter', 'other')));
CREATE TABLE `properties` (
    `id` TEXT PRIMARY KEY NOT NULL,
    `name` TEXT NOT NULL,
    `owner_person_id` TEXT NOT NULL,
    `status` TEXT NOT NULL DEFAULT 'active' CHECK(`status` IN ('active', 'inactive')),
    `created_at` INTEGER NOT NULL,
    `updated_at` INTEGER NOT NULL,
    `deleted_at` INTEGER,
    FOREIGN KEY (`owner_person_id`) REFERENCES `persons`(`id`) ON UPDATE NO ACTION ON DELETE NO ACTION
);
CREATE TABLE `accounts` (
    `id` TEXT PRIMARY KEY NOT NULL,
    `name` TEXT NOT NULL,
    `person_id` TEXT NOT NULL,
    `property_id` TEXT,
    `account_type` TEXT NOT NULL CHECK(`account_type` IN ('bank', 'cash')),
    `opening_balance` REAL NOT NULL DEFAULT 0,
    `current_balance` REAL NOT NULL DEFAULT 0,
    `created_at` INTEGER NOT NULL,
    `updated_at` INTEGER NOT NULL,
    `deleted_at` INTEGER, `account_alias` TEXT, `bank_name` TEXT, `account_number` TEXT, is_business_account INTEGER NOT NULL DEFAULT 0,
    FOREIGN KEY (`person_id`) REFERENCES `persons`(`id`) ON UPDATE NO ACTION ON DELETE NO ACTION,
    FOREIGN KEY (`property_id`) REFERENCES `properties`(`id`) ON UPDATE NO ACTION ON DELETE NO ACTION
);
CREATE TABLE `categories` (
    `id` TEXT PRIMARY KEY NOT NULL,
    `name` TEXT NOT NULL,
    `type` TEXT NOT NULL CHECK(`type` IN ('income', 'expense')),
    `icon` TEXT,
    `color` TEXT,
    `created_at` INTEGER NOT NULL,
    `updated_at` INTEGER NOT NULL,
    `deleted_at` INTEGER
, `is_active` INTEGER NOT NULL DEFAULT 1);
CREATE TABLE `recurring_schedules` (
    `id` TEXT PRIMARY KEY NOT NULL,
    `title` TEXT NOT NULL,
    `amount` REAL NOT NULL,
    `frequency` TEXT NOT NULL CHECK(`frequency` IN ('daily', 'weekly', 'monthly', 'yearly')),
    `start_date` INTEGER NOT NULL,
    `next_run_date` INTEGER NOT NULL,
    `owner_person_id` TEXT NOT NULL,
    `payer_person_id` TEXT NOT NULL,
    `category_id` TEXT,
    `status` TEXT NOT NULL DEFAULT 'active' CHECK(`status` IN ('active', 'paused', 'terminated')),
    `created_at` INTEGER NOT NULL,
    `updated_at` INTEGER NOT NULL,
    `deleted_at` INTEGER,
    FOREIGN KEY (`owner_person_id`) REFERENCES `persons`(`id`) ON UPDATE NO ACTION ON DELETE NO ACTION,
    FOREIGN KEY (`payer_person_id`) REFERENCES `persons`(`id`) ON UPDATE NO ACTION ON DELETE NO ACTION,
    FOREIGN KEY (`category_id`) REFERENCES `categories`(`id`) ON UPDATE NO ACTION ON DELETE NO ACTION
);
CREATE TABLE `budgets` (
    `id` TEXT PRIMARY KEY NOT NULL,
    `category_id` TEXT NOT NULL,
    `property_id` TEXT,
    `amount` REAL NOT NULL,
    `month` INTEGER NOT NULL,
    `year` INTEGER NOT NULL,
    `created_at` INTEGER NOT NULL,
    `updated_at` INTEGER NOT NULL,
    `deleted_at` INTEGER,
    FOREIGN KEY (`category_id`) REFERENCES `categories`(`id`) ON UPDATE NO ACTION ON DELETE NO ACTION,
    FOREIGN KEY (`property_id`) REFERENCES `properties`(`id`) ON UPDATE NO ACTION ON DELETE NO ACTION
);
CREATE TABLE `ocr_results` (
    `id` TEXT PRIMARY KEY NOT NULL,
    `attachment_id` TEXT NOT NULL,
    `raw_payload` TEXT NOT NULL,
    `detected_amount` REAL,
    `detected_date` INTEGER,
    `confidence_score` REAL,
    `created_at` INTEGER NOT NULL,
    `updated_at` INTEGER NOT NULL,
    `deleted_at` INTEGER,
    FOREIGN KEY (`attachment_id`) REFERENCES `attachments`(`id`) ON UPDATE NO ACTION ON DELETE NO ACTION
);
CREATE TABLE `line_accounts` (
    `id` TEXT PRIMARY KEY NOT NULL,
    `user_id` TEXT NOT NULL UNIQUE,
    `line_user_id` TEXT NOT NULL UNIQUE,
    `display_name` TEXT,
    `picture_url` TEXT,
    `notify_enabled` INTEGER NOT NULL DEFAULT 1,
    `created_at` INTEGER NOT NULL,
    `updated_at` INTEGER NOT NULL,
    `deleted_at` INTEGER,
    FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE NO ACTION ON DELETE NO ACTION
);
CREATE TABLE `auth_sessions` (
  `id` TEXT PRIMARY KEY NOT NULL,
  `expires_at` INTEGER NOT NULL,
  `ip_address` TEXT,
  `user_agent` TEXT,
  `user_id` TEXT NOT NULL,
  FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE
);
CREATE TABLE `auth_accounts` (
  `id` TEXT PRIMARY KEY NOT NULL,
  `account_id` TEXT NOT NULL,
  `provider_id` TEXT NOT NULL,
  `user_id` TEXT NOT NULL,
  `access_token` TEXT,
  `refresh_token` TEXT,
  `id_token` TEXT,
  `expires_at` INTEGER,
  `password` TEXT,
  FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE
);
CREATE TABLE `auth_verifications` (
  `id` TEXT PRIMARY KEY NOT NULL,
  `identifier` TEXT NOT NULL,
  `value` TEXT NOT NULL,
  `expires_at` INTEGER NOT NULL,
  `created_at` INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS "transactions" (
    `id` TEXT PRIMARY KEY NOT NULL,
    `type` TEXT NOT NULL CHECK(`type` IN ('income', 'expense', 'transfer', 'adjustment')),
    `amount` REAL NOT NULL,
    `date` INTEGER NOT NULL,
    `title` TEXT NOT NULL,
    `owner_person_id` TEXT,
    `payer_person_id` TEXT,
    `property_id` TEXT,
    `category_id` TEXT,
    `source_account_id` TEXT,
    `destination_account_id` TEXT,
    `status` TEXT NOT NULL DEFAULT 'completed' CHECK(`status` IN ('pending', 'completed', 'cancelled')),
    `business_status` TEXT CHECK(`business_status` IN ('pending', 'received')),
    `note` TEXT,
    `adjustment_reason` TEXT,
    `adjustment_direction` TEXT CHECK(`adjustment_direction` IN ('increase', 'decrease')),
    `created_by_user_id` TEXT NOT NULL,
    `recurring_schedule_id` TEXT,
    `created_at` INTEGER NOT NULL,
    `updated_at` INTEGER NOT NULL,
    `deleted_at` INTEGER,
    FOREIGN KEY (`owner_person_id`) REFERENCES `persons`(`id`),
    FOREIGN KEY (`payer_person_id`) REFERENCES `persons`(`id`),
    FOREIGN KEY (`property_id`) REFERENCES `properties`(`id`),
    FOREIGN KEY (`category_id`) REFERENCES `categories`(`id`),
    FOREIGN KEY (`source_account_id`) REFERENCES `accounts`(`id`),
    FOREIGN KEY (`destination_account_id`) REFERENCES `accounts`(`id`),
    FOREIGN KEY (`created_by_user_id`) REFERENCES `users`(`id`)
);
CREATE TABLE IF NOT EXISTS "activity_logs" (
    `id` TEXT PRIMARY KEY NOT NULL,
    `user_id` TEXT NOT NULL,
    `action` TEXT NOT NULL CHECK(
        `action` IN ('CREATE', 'UPDATE', 'DELETE', 'RESTORE', 'RECONCILE')
    ),
    `entity` TEXT NOT NULL,
    `entity_id` TEXT NOT NULL,
    `old_value` TEXT,
    `new_value` TEXT,
    `created_at` INTEGER NOT NULL,
    FOREIGN KEY (`user_id`) REFERENCES `users`(`id`)
        ON UPDATE NO ACTION ON DELETE NO ACTION
);
CREATE TABLE IF NOT EXISTS "attachments" (
    id TEXT PRIMARY KEY NOT NULL,
    transaction_id TEXT NOT NULL,
    file_key TEXT NOT NULL,
    file_name TEXT NOT NULL,
    file_type TEXT NOT NULL,
    file_size INTEGER NOT NULL,
    width INTEGER,
    height INTEGER,
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    deleted_at INTEGER,
    FOREIGN KEY (transaction_id) REFERENCES transactions(id) ON DELETE NO ACTION
);
CREATE TABLE `notification_settings` (
  `id` text PRIMARY KEY,
  `user_id` text NOT NULL,
  `notification_type` text NOT NULL,
  `settings` text NOT NULL DEFAULT '{}',
  `enabled` integer NOT NULL DEFAULT 1,
  `created_at` integer NOT NULL,
  `updated_at` integer NOT NULL,
  UNIQUE(`user_id`, `notification_type`)
);
DELETE FROM sqlite_sequence;
CREATE INDEX `users_deleted_idx` ON `users` (`deleted_at`);
CREATE INDEX `persons_deleted_idx` ON `persons` (`deleted_at`);
CREATE INDEX `properties_owner_idx` ON `properties` (`owner_person_id`);
CREATE INDEX `properties_deleted_idx` ON `properties` (`deleted_at`);
CREATE INDEX `accounts_person_idx` ON `accounts` (`person_id`);
CREATE INDEX `accounts_property_idx` ON `accounts` (`property_id`);
CREATE INDEX `accounts_deleted_idx` ON `accounts` (`deleted_at`);
CREATE INDEX `categories_deleted_idx` ON `categories` (`deleted_at`);
CREATE INDEX `sessions_user_idx` ON `auth_sessions` (`user_id`);
CREATE INDEX `accounts_auth_user_idx` ON `auth_accounts` (`user_id`);
CREATE INDEX `verifications_identifier_idx` ON `auth_verifications` (`identifier`);
CREATE INDEX accounts_business_idx ON accounts(is_business_account);
CREATE INDEX `transactions_date_idx` ON `transactions` (`date`);
CREATE INDEX `transactions_support_idx` ON `transactions` (`payer_person_id`, `owner_person_id`, `type`, `status`, `deleted_at`);
CREATE INDEX `transactions_property_idx` ON `transactions` (`property_id`);
CREATE INDEX `transactions_deleted_idx` ON `transactions` (`deleted_at`);
CREATE INDEX `transactions_business_status_idx` ON `transactions` (`business_status`);
CREATE INDEX `transactions_source_account_idx`     ON `transactions` (`source_account_id`);
CREATE INDEX `transactions_destination_account_idx`     ON `transactions` (`destination_account_id`);
CREATE INDEX `logs_entity_idx`
    ON `activity_logs` (`entity`, `entity_id`);
CREATE INDEX attachments_transaction_idx ON attachments (transaction_id);
CREATE INDEX attachments_deleted_idx ON attachments (deleted_at);
CREATE INDEX `notification_settings_user_idx` ON `notification_settings` (`user_id`);
CREATE INDEX `notification_settings_type_idx` ON `notification_settings` (`notification_type`);
